using System.ComponentModel;
using System.Net;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

builder.Logging.SetMinimumLevel(LogLevel.Warning);

builder.Services.AddChatClient(pipeline => pipeline
    .UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddSingleton<NoteService>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient, new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Description = "An agent that researches topics by searching the web and taking notes.",
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools =
        [
            AIFunctionFactory.Create(researchTools.SearchWebAsync),
            AIFunctionFactory.Create(researchTools.AddNoteAsync),
            AIFunctionFactory.Create(researchTools.GetAllNotesAsync),
        ],
    },
});

const string instructions = """
    You are a research agent. Your job is to research a topic thoroughly by:
    1. Searching the web for relevant information using the SearchWebAsync tool
    2. Taking notes on key findings using the AddNoteAsync tool
    3. Performing multiple searches to cover different angles of the topic
    4. Reviewing your notes with GetAllNotesAsync, then producing a final summary

    Always take notes on important findings before moving to the next search.
    When you have gathered enough information, compile your notes into a
    comprehensive summary and present it to the user.
    """;

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");

while (true)
{
    Console.Write("\n> ");
    var topic = Console.ReadLine()?.Trim();

    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }

    var noteService = host.Services.GetRequiredService<NoteService>();
    noteService.Clear();

    Console.WriteLine($"\nResearching: {topic}\n");

    var session = await agent.CreateSessionAsync();

    var systemMessage = new ChatMessage(ChatRole.System, instructions);
    var userMessage = new ChatMessage(ChatRole.User,
        $"Research the following topic and provide a comprehensive summary: {topic}");

    await foreach (var update in agent.RunStreamingAsync(
        [systemMessage, userMessage], session))
    {
        if (!string.IsNullOrEmpty(update.Text))
        {
            Console.Write(update.Text);
        }
    }

    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

/// <summary>Stores notes collected during research.</summary>
public sealed class NoteService
{
    private readonly List<string> _notes = [];

    public void Add(string note)
    {
        _notes.Add(note);
    }

    public IReadOnlyList<string> GetAll() => _notes.AsReadOnly();

    public void Clear() => _notes.Clear();
}

/// <summary>Tools available to the research agent.</summary>
public sealed class ResearchTools(NoteService noteService, ILogger<ResearchTools> logger)
{
    private static readonly HttpClient HttpClient = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information on a query. Returns relevant search result snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        logger.LogDebug("Searching web for: {Query}", query);

        try
        {
            var encodedQuery = WebUtility.UrlEncode(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encodedQuery}";

            var response = await HttpClient.GetAsync(url, cancellationToken);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync(cancellationToken);
            var snippets = ExtractSnippets(html);

            if (snippets.Count == 0)
            {
                return $"No results found for '{query}'.";
            }

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for '{query}':");
            for (var i = 0; i < Math.Min(snippets.Count, 5); i++)
            {
                sb.AppendLine($"  {i + 1}. {snippets[i]}");
            }

            return sb.ToString();
        }
        catch (Exception ex) when (ex is HttpRequestException or TaskCanceledException)
        {
            logger.LogWarning(ex, "Web search failed for query: {Query}", query);
            return $"Search failed for '{query}': {ex.Message}. Try a different query.";
        }
    }

    [Description("Add a research note capturing a key finding.")]
    public Task<string> AddNoteAsync(
        [Description("The note text to save")] string note,
        CancellationToken cancellationToken = default)
    {
        noteService.Add(note);
        logger.LogDebug("Note added. Total notes: {Count}", noteService.GetAll().Count);
        return Task.FromResult($"Note saved. You now have {noteService.GetAll().Count} note(s).");
    }

    [Description("Retrieve all research notes collected so far.")]
    public Task<string> GetAllNotesAsync(CancellationToken cancellationToken = default)
    {
        var notes = noteService.GetAll();
        if (notes.Count == 0)
        {
            return Task.FromResult("No notes taken yet.");
        }

        var sb = new StringBuilder();
        sb.AppendLine($"Research notes ({notes.Count} total):");
        for (var i = 0; i < notes.Count; i++)
        {
            sb.AppendLine($"  [{i + 1}] {notes[i]}");
        }

        return Task.FromResult(sb.ToString());
    }

    private static List<string> ExtractSnippets(string html)
    {
        var snippets = new List<string>();

        // Extract result snippets from DuckDuckGo Lite
        var tdClassResult = "class=\"result-snippet\"";
        var searchPos = 0;
        while (searchPos < html.Length)
        {
            var snippetStart = html.IndexOf(tdClassResult, searchPos, StringComparison.Ordinal);
            if (snippetStart < 0)
            {
                break;
            }

            var contentStart = html.IndexOf('>', snippetStart) + 1;
            if (contentStart <= 0)
            {
                break;
            }

            var contentEnd = html.IndexOf("</td>", contentStart, StringComparison.Ordinal);
            if (contentEnd < 0)
            {
                break;
            }

            var snippet = html[contentStart..contentEnd];
            snippet = StripHtml(snippet).Trim();
            if (!string.IsNullOrWhiteSpace(snippet) && snippet.Length > 20)
            {
                snippets.Add(snippet);
            }

            searchPos = contentEnd + 1;
        }

        // Also extract link text for source titles
        var spanTag = "<span class=\"link-text\">";
        searchPos = 0;
        while (searchPos < html.Length && snippets.Count < 10)
        {
            var linkStart = html.IndexOf(spanTag, searchPos, StringComparison.Ordinal);
            if (linkStart < 0)
            {
                break;
            }

            var textStart = linkStart + spanTag.Length;
            var textEnd = html.IndexOf("</span>", textStart, StringComparison.Ordinal);
            if (textEnd < 0)
            {
                break;
            }

            var text = StripHtml(html[textStart..textEnd]).Trim();
            if (!string.IsNullOrWhiteSpace(text) && text.Length > 10)
            {
                snippets.Add($"[Source] {text}");
            }

            searchPos = textEnd + 1;
        }

        return snippets;
    }

    private static string StripHtml(string html)
    {
        var sb = new StringBuilder(html.Length);
        var insideTag = false;

        foreach (var c in html)
        {
            switch (c)
            {
                case '<':
                    insideTag = true;
                    break;
                case '>':
                    insideTag = false;
                    break;
                default:
                    if (!insideTag)
                    {
                        sb.Append(c);
                    }

                    break;
            }
        }

        return WebUtility.HtmlDecode(sb.ToString());
    }
}

