            var text = StripHtml(html[textStart..textEnd]).Trim();
            if (!string.IsNullOrWhiteSpace(text) && text.Length > 10)
            {
                snippets.Add($"[Source] {text}");
            }

            searchPos = textEnd + 1;
        }

        return snippets;
    }

